            conditions: array[string]
            notes: string
            restrictions: array[string]
        }
        emergencyContact: {
            name: string
            relationship: string
            phone: string --somente digitos
        }
    } (optional)
    onboardingCompleted: bool
    termsAcceptedAt: string (iso8601) (optional)
}

